// Extract and normalize the RFI intake payload.
const first = $input.first().json;
const body = first.body && typeof first.body === 'object' ? first.body : first;
const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const dateStr = now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate());
const ts = dateStr + ' ' + pad(now.getHours()) + ':' + pad(now.getMinutes());
const rfi_id = String(body.rfi_id || ('RFI-' + dateStr.replace(/-/g, '') + '-' + Math.random().toString(36).slice(2, 6).toUpperCase()));
return [{
  json: {
    rfi_id: rfi_id,
    project_name: String(body.project_name || '').trim(),
    discipline: String(body.discipline || '').trim(),
    submitter: String(body.submitter || '').trim(),
    submitter_email: String(body.submitter_email || '').trim(),
    question: String(body.question || '').trim(),
    due_date: String(body.due_date || '').trim(),
    status: 'open',
    received_at: ts
  }
}];

// Deterministic urgency + discipline hint. No AI arithmetic.
const it = $input.first().json;
const now = new Date();
const parse = (s) => { const d = new Date(String(s)); return isNaN(d.getTime()) ? null : d; };
const due = parse(it.due_date);
let days = null;
if (due) days = Math.floor((due.getTime() - now.getTime()) / 86400000 + 0.000001);
const q = String(it.question || '').toLowerCase();
const kw = {
  structural: ['structural', 'beam', 'column', 'slab', 'foundation', 'concrete', 'steel', 'rebar', 'shoring'],
  mechanical: ['mechanical', 'hvac', 'duct', 'chiller', 'pump', 'ventilation', 'exhaust'],
  electrical: ['electrical', 'cable', 'panel', 'conduit', 'lighting', 'breaker', 'power', 'switchgear'],
  architectural: ['architect', 'finish', 'door', 'window', 'ceiling', 'wall', 'tile', 'facade', 'millwork']
};
let discipline = '';
for (const [k, words] of Object.entries(kw)) {
  if (words.some((w) => q.includes(w))) { discipline = k; break; }
}
let priority = 'low';
if (days !== null && days <= 2) priority = 'high';
else if (days !== null && days <= 5) priority = 'medium';
if (q.includes('critical path') || q.includes('stop work') || q.includes('shutdown')) priority = 'high';
const urgent = priority === 'high';
return [{
  json: {
    ...it,
    days_until_due: days,
    priority: priority,
    discipline: it.discipline || discipline,
    urgent: urgent,
    urgency_reason: urgent ? 'Due within 2 days or high impact wording' : 'Normal timeline'
  }
}];

// Parse the AI ack draft; fall back to a deterministic ack.
const it = $input.first().json;
let raw = String(it.output != null ? it.output : '').trim();
raw = raw.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
let p = {};
const m = raw.match(/\{[\s\S]*\}/);
if (m) { try { p = JSON.parse(m[0]); } catch (e) { try { p = JSON.parse(m[0].replace(/'/g, '"')); } catch (e2) {} } }
let ctx = it;
try { ctx = $('Compute RFI Urgency').first().json; } catch (e) {}
const clean = (s) => String(s || '').replace(/[\u2014\u2013]/g, '-');
const fallbackSubj = 'RFI ' + ctx.rfi_id + ' received: ' + String(ctx.question || '').slice(0, 60);
const fallbackBody = 'Hi ' + (ctx.submitter || 'there') + ',\n\nThank you for your RFI on ' + ctx.project_name + ' (' + ctx.discipline + '). We received it and it is being reviewed.\n\nQuestion: ' + ctx.question + '\n\nLook for a response before ' + ctx.due_date + '.\n\nProject coordination team';
return [{
  json: {
    rfi_id: ctx.rfi_id, project_name: ctx.project_name, discipline: ctx.discipline,
    submitter: ctx.submitter, submitter_email: ctx.submitter_email, question: ctx.question,
    due_date: ctx.due_date, priority: ctx.priority, days_until_due: ctx.days_until_due,
    urgent: ctx.urgent === true,
    question_type: clean(p.question_type || 'other'),
    needs_engineer: p.needs_engineer === true || p.needs_engineer === 'true' || ctx.urgent === true,
    ack_subject: clean(p.ack_subject || fallbackSubj),
    ack_body: clean(p.ack_body || fallbackBody),
    received_at: ctx.received_at
  }
}];

// Normalize the RFI answer payload.
const first = $input.first().json;
const body = first.body && typeof first.body === 'object' ? first.body : first;
return [{
  json: {
    rfi_id: String(body.rfi_id || '').trim().toUpperCase(),
    answer_text: String(body.answer_text || '').trim(),
    answered_by: String(body.answered_by || '').trim()
  }
}];

// Match the answer rfi_id against the RFI Register.
const rows = $input.all().map((i) => i.json);
const ctx = $('Normalize Answer').first().json;
const rid = String(ctx.rfi_id || '').trim().toUpperCase();
const rec = rows.map((r) => r.fields || r).find((r) => String(r.rfi_id || '').trim().toUpperCase() === rid);
if (!rec) return [{ json: { found: false, rfi_id: rid, answer_text: ctx.answer_text, answered_by: ctx.answered_by } }];
return [{
  json: {
    found: true,
    record_id: rec.id,
    rfi_id: rid,
    answer_text: ctx.answer_text,
    answered_by: ctx.answered_by,
    submitter_email: String(rec.submitter_email || ''),
    submitter: String(rec.submitter || ''),
    project_name: String(rec.project_name || ''),
    question: String(rec.question || ''),
    answered_at: (() => { const n = new Date(); const p = (x) => String(x).padStart(2, '0'); return n.getFullYear() + '-' + p(n.getMonth() + 1) + '-' + p(n.getDate()) + ' ' + p(n.getHours()) + ':' + p(n.getMinutes()); })()
  }
}];

// Extract and normalize the submittal intake payload.
const first = $input.first().json;
const body = first.body && typeof first.body === 'object' ? first.body : first;
const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const dateStr = now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate());
const ts = dateStr + ' ' + pad(now.getHours()) + ':' + pad(now.getMinutes());
const sub_id = String(body.sub_id || ('SUB-' + dateStr.replace(/-/g, '') + '-' + Math.random().toString(36).slice(2, 6).toUpperCase()));
return [{
  json: {
    sub_id: sub_id,
    project_name: String(body.project_name || '').trim(),
    item_name: String(body.item_name || '').trim(),
    spec_section: String(body.spec_section || '').trim(),
    submitter: String(body.submitter || '').trim(),
    submitter_email: String(body.submitter_email || '').trim(),
    due_date: String(body.due_date || '').trim(),
    status: 'submitted',
    received_at: ts
  }
}];

// Parse the AI submittal classification; fall back to defaults.
const it = $input.first().json;
let raw = String(it.output != null ? it.output : '').trim();
raw = raw.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
let p = {};
const m = raw.match(/\{[\s\S]*\}/);
if (m) { try { p = JSON.parse(m[0]); } catch (e) { try { p = JSON.parse(m[0].replace(/'/g, '"')); } catch (e2) {} } }
let ctx = it;
try { ctx = $('Normalize Submittal').first().json; } catch (e) {}
const clean = (s) => String(s || '').replace(/[\u2014\u2013]/g, '-');
const fallbackSubj = 'Submittal ' + ctx.sub_id + ' received: ' + String(ctx.item_name || '').slice(0, 60);
const fallbackBody = 'Hi ' + (ctx.submitter || 'there') + ',\n\nWe received your submittal for ' + ctx.item_name + ' on ' + ctx.project_name + '. It is being routed for review.\n\nLook for a decision before ' + ctx.due_date + '.\n\nDocument control team';
return [{
  json: {
    sub_id: ctx.sub_id, project_name: ctx.project_name, item_name: ctx.item_name,
    spec_section: ctx.spec_section, submitter: ctx.submitter, submitter_email: ctx.submitter_email,
    due_date: ctx.due_date, received_at: ctx.received_at,
    sub_type: clean(p.sub_type || 'other'),
    reviewer: clean(p.reviewer || 'project manager'),
    ack_subject: clean(p.ack_subject || fallbackSubj),
    ack_body: clean(p.ack_body || fallbackBody)
  }
}];

// Combine open RFIs + submitted submittals into a daily summary.
const subsJson = $input.first().json.records || [];
let rfisJson = [];
try { rfisJson = $('Fetch Open RFIs').first().json.records || []; } catch (e) {}
const subs = subsJson;
const rfis = rfisJson;
const now = new Date();
const parse = (s) => { const d = new Date(String(s)); return isNaN(d.getTime()) ? null : d; };
const dayDiff = (s) => { const d = parse(s); if (!d) return null; return Math.floor((d.getTime() - now.getTime()) / 86400000 + 0.000001); };
const lines = [];
let openRfi = 0, openSub = 0, dueToday = 0, overdue = 0;
const seenR = new Set();
for (const r of rfis.map((r) => r.fields || r)) {
  if (String(r.status || 'open') !== 'answered') {
    if (seenR.has(String(r.rfi_id))) continue;
    seenR.add(String(r.rfi_id));
    openRfi++;
    const dd = dayDiff(r.due_date);
    if (dd !== null && dd < 0) { overdue++; lines.push('OVERDUE RFI ' + r.rfi_id + ' (' + r.project_name + ') due ' + r.due_date); }
    else if (dd === 0) { dueToday++; lines.push('RFI ' + r.rfi_id + ' due TODAY (' + r.project_name + ')'); }
    else if (dd !== null && dd <= 2) { lines.push('RFI ' + r.rfi_id + ' due in ' + dd + 'd (' + r.project_name + ')'); }
  }
}
const seenS = new Set();
for (const s of subs.map((s) => s.fields || s)) {
  if (String(s.status || 'submitted') === 'submitted') {
    if (seenS.has(String(s.sub_id))) continue;
    seenS.add(String(s.sub_id));
    openSub++;
    const dd = dayDiff(s.due_date);
    if (dd !== null && dd < 0) { overdue++; lines.push('OVERDUE submittal ' + s.sub_id + ' (' + s.item_name + ')'); }
    else if (dd === 0) { dueToday++; lines.push('Submittal ' + s.sub_id + ' due TODAY (' + s.item_name + ')'); }
    else if (dd !== null && dd <= 2) { lines.push('Submittal ' + s.sub_id + ' due in ' + dd + 'd (' + s.item_name + ')'); }
  }
}
const hasItems = lines.length > 0;
return [{
  json: {
    has_items: hasItems,
    open_rfis: openRfi,
    open_submittals: openSub,
    due_today: dueToday,
    overdue: overdue,
    detail: lines.join('\n') || 'All clear',
    summary_text: 'Daily construction document sweep\n\nOpen RFIs: ' + openRfi + '\nOpen submittals: ' + openSub + '\nDue today: ' + dueToday + '\nOverdue: ' + overdue + '\n\n' + (lines.length ? lines.join('\n') : 'All clear, nothing due.')
  }
}];
